    method: str,
    environ: dict[str, Any],
    raw_id: str,
    start_response: StartResponse,
) -> Iterable[bytes]:
    if method != "GET":
        return _error(
            start_response,
            "405 Method Not Allowed",
            "method_not_allowed",
            f"Method {method} is not allowed for this path.",
            allowed="GET",
        )

    id_error = _validate_path_id(raw_id)
    if id_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", id_error
        )
    query_error = _query_parameter_error(environ)
    if query_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", query_error
        )

    if store.get(raw_id) is None:
        return _error(
            start_response,
            "404 Not Found",
            "resource_not_found",
            "No resource exists with the requested id.",
        )

    try:
        body = content_store.get_content(raw_id)
    except ContentError as exc:
        return _error(
            start_response, "409 Conflict", exc.code, exc.message
        )

    raw_range = environ.get(_RANGE_HEADER)
    if raw_range is None:
        # Without a range condition the finalized artifact is returned whole
        # as raw bytes only: no JSON wrapper and no trailing newline.
        start_response(
            "200 OK",
            [
                ("Content-Type", "application/octet-stream"),
                ("Content-Length", str(len(body))),
            ],
        )
        return [body]

    if not isinstance(raw_range, str):
        raw_range = str(raw_range)
    try:
        interval = _parse_byte_range(raw_range, len(body))
    except RangeNotSatisfiable as exc:
        return _error(
            start_response,
            "416 Range Not Satisfiable",
            "range_not_satisfiable",
            "Requested byte range is not satisfiable.",
            extra_headers=[("Content-Range", f"bytes */{exc.size}")],
        )
    if interval is None:
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            "Range header must be a single byte range, e.g. 'bytes=0-99'.",
        )

    start, end = interval
    partial = body[start : end + 1]
    # Only the hit raw bytes are returned; the length header is the exact
    # segment size and Content-Range names the positions and total length.
    start_response(
        "206 Partial Content",
        [
            ("Content-Type", "application/octet-stream"),
            ("Content-Length", str(len(partial))),
            ("Content-Range", f"bytes {start}-{end}/{len(body)}"),
        ],
    )
    return [partial]

