import io, json, hashlib
from provenance_api.app import application, reset_state

reset_state()

def call(method, path, body=b"", headers=None):
    environ = {"REQUEST_METHOD": method, "PATH_INFO": path,
               "wsgi.input": io.BytesIO(body), "CONTENT_LENGTH": str(len(body))}
    for k, v in (headers or {}).items():
        environ[k] = v
    captured = {}
    def sr(status, hdrs):
        captured["status"] = status; captured["headers"] = hdrs
    parts = application(environ, sr)
    return captured["status"], captured["headers"], b"".join(parts)

# register resource + upload + assemble
payload = b"0123456789"
digest = hashlib.sha256(payload).hexdigest()
_, _, raw = call("POST", "/resources", json.dumps({"name":"r","category":"code","digest":digest}).encode(), {"CONTENT_TYPE":"application/json"})
rid = json.loads(raw)["id"]
ch = {"CONTENT_TYPE":"application/octet-stream","HTTP_X_TOTAL_CHUNKS":"1","HTTP_X_CONTENT_DIGEST":digest}
call("POST", f"/resources/{rid}/chunks/0", payload, ch)
call("POST", f"/resources/{rid}/assemble")

for rng in [None, "bytes=0-3", "bytes=4-", "bytes=-3", "bytes=8-9999", "-100",
